<?php
namespace Delnavazan\Platform\Core\Infrastructure\Repository;

use Delnavazan\Platform\Core\Application\ProviderIntegrationRule;

/** Persistence boundary for one Teacher response to one delivered introductory booking request. */
final class BookingTeacherResponseRepository {
    private string $p;
    public function __construct(){global $wpdb;$this->p=$wpdb->prefix.'dzn_';}
    public function begin():void{global $wpdb;if($wpdb->query('SET TRANSACTION ISOLATION LEVEL READ COMMITTED')===false||$wpdb->query('START TRANSACTION')===false)throw new \RuntimeException('Transaction start failed');}
    public function commit():void{global $wpdb;if($wpdb->query('COMMIT')===false)throw new \RuntimeException('Transaction commit failed');}
    public function rollback():void{global $wpdb;$wpdb->query('ROLLBACK');}

    public function teacherForUser(int $userId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT t.id,t.status,t.archived_at,t.timezone,o.state onboarding_state,o.readiness_state FROM {$this->p}teacher_principal_links l INNER JOIN {$this->p}teachers t ON t.id=l.teacher_id INNER JOIN {$this->p}teacher_onboarding_states o ON o.teacher_id=t.id WHERE l.wordpress_user_id=%d AND l.status='active' AND l.revoked_at IS NULL LIMIT 1{$suffix}",$userId))?:null;}
    public function teacherForAdministrator(int $teacherId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT t.id,t.status,t.archived_at,t.timezone,o.state onboarding_state,o.readiness_state FROM {$this->p}teachers t INNER JOIN {$this->p}teacher_onboarding_states o ON o.teacher_id=t.id WHERE t.id=%d LIMIT 1{$suffix}",$teacherId))?:null;}
    public function deliveryByUid(string $uid,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT d.*,r.lifecycle_status,r.resolution_state,r.privacy_erased_at,r.selected_intro_course_id,r.student_id,s.country request_country,rt.starts_at_utc,rt.instructional_ends_at_utc,rt.occupied_ends_at_utc,rt.local_date,rt.local_start_time,rt.timezone request_timezone FROM {$this->p}booking_request_teacher_deliveries d INNER JOIN {$this->p}booking_requests r ON r.id=d.booking_request_id INNER JOIN {$this->p}booking_request_contact_snapshots s ON s.booking_request_id=r.id AND s.snapshot_sequence=1 INNER JOIN {$this->p}booking_request_requested_times rt ON rt.id=d.requested_time_id AND rt.booking_request_id=r.id WHERE d.uid=%s{$suffix}",$uid))?:null;}
    public function requestByUid(string $uid,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_requests WHERE uid=%s{$suffix}",$uid))?:null;}
    public function requestedTime(int $requestId,int $timeId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_requested_times WHERE id=%d AND booking_request_id=%d{$suffix}",$timeId,$requestId))?:null;}
    public function deliveryForRequest(int $requestId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_teacher_deliveries WHERE booking_request_id=%d{$suffix}",$requestId))?:null;}
    public function offerForTeacher(int $requestId,int $teacherId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_allocation_offers WHERE booking_request_id=%d AND teacher_id=%d{$suffix}",$requestId,$teacherId))?:null;}
    public function confirmationForRequest(int $requestId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_confirmations WHERE booking_request_id=%d ORDER BY id DESC LIMIT 1{$suffix}",$requestId))?:null;}
    public function delivery(int $id,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT d.*,r.lifecycle_status,r.resolution_state,r.privacy_erased_at,r.selected_intro_course_id,r.student_id,s.country request_country,rt.starts_at_utc,rt.instructional_ends_at_utc,rt.occupied_ends_at_utc,rt.local_date,rt.local_start_time,rt.timezone request_timezone FROM {$this->p}booking_request_teacher_deliveries d INNER JOIN {$this->p}booking_requests r ON r.id=d.booking_request_id INNER JOIN {$this->p}booking_request_contact_snapshots s ON s.booking_request_id=r.id AND s.snapshot_sequence=1 INNER JOIN {$this->p}booking_request_requested_times rt ON rt.id=d.requested_time_id AND rt.booking_request_id=r.id WHERE d.id=%d{$suffix}",$id))?:null;}
    /** @param list<array{starts_at_utc:string,occupied_ends_at_utc:string}> $times */
    public function studentOccupancyConflicts(int $studentId,array $times,array $options=array()):array{return StudentOccupancyQuery::conflicts($studentId,$times,$options);}
    public function ensureAndLockStudentRoot(int $studentId,string $now,int $actor):void{(new CanonicalLessonScheduleRepository())->ensureAndLockStudentRoot($studentId,$now,$actor);}
    public function ensureAndLockTeacherRoot(int $teacherId,string $now,int $actor):void{(new CanonicalLessonScheduleRepository())->ensureAndLockTeacherRoot($teacherId,$now,$actor);}
    public function teacherOccupancyConflicts(int $teacherId,string $startsAtUtc,string $occupiedEndUtc,int $excludeBookingRequestId=0):array{return (new \Delnavazan\Platform\Core\Application\BookingTeacherOccupancyReadService())->overlapping($teacherId,$startsAtUtc,$occupiedEndUtc,0,$excludeBookingRequestId,false);}
    public function activeConnection(int $teacherId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT c.* FROM {$this->p}integration_connections c INNER JOIN {$this->p}integration_credentials k ON k.connection_id=c.id AND k.state='active' WHERE c.provider_code='google_calendar' AND c.teacher_id=%d AND c.connection_state='connected' AND c.active_slot=1 AND c.identity_state='verified' AND BINARY c.scope_snapshot = BINARY %s ORDER BY c.id DESC LIMIT 1{$suffix}",$teacherId,ProviderIntegrationRule::GOOGLE_CALENDAR_SCOPE))?:null;}
    public function credential(int $connectionId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}integration_credentials WHERE connection_id=%d AND state='active' ORDER BY id DESC LIMIT 1",$connectionId))?:null;}
    public function command(string $digest):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_teacher_commands WHERE command_key_digest=%s",$digest))?:null;}
    public function confirmationForDelivery(int $deliveryId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_confirmations WHERE delivery_id=%d{$suffix}",$deliveryId))?:null;}
    /** The one current offer slot, if allocation has started to re-offer the request. */
    public function activeAllocationOffer(int $requestId,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_allocation_offers WHERE booking_request_id=%d AND active_slot=1{$suffix}",$requestId))?:null;}
    public function confirmation(int $id,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_confirmations WHERE id=%d{$suffix}",$id))?:null;}
    public function retryableConfirmations(int $limit=10):array{global $wpdb;$limit=max(1,min(25,$limit));return (array)$wpdb->get_results("SELECT * FROM {$this->p}booking_request_confirmations WHERE state IN ('pending_projection','awaiting_conference','retryable') AND (next_attempt_at IS NULL OR next_attempt_at<=UTC_TIMESTAMP()) ORDER BY id LIMIT {$limit}");}
    public function projectionSecret(int $confirmationId):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}provider_projection_secrets WHERE mapping_kind='booking_calendar' AND mapping_id=%d AND active_slot=1",$confirmationId))?:null;}

    public function insertConfirmation(array $data):int{return $this->insert('booking_request_confirmations',$data);}
    public function insertCommand(array $data):int{return $this->insert('booking_request_teacher_commands',$data);}
    public function insertSecret(array $data):int{return $this->insert('provider_projection_secrets',$data);}
    public function insertNotification(array $data):int{return $this->insert('booking_request_student_notifications',$data);}
    /** Student receipt is stable across offer rotation; Teacher notices use the offer ledger. */
    public function queueRequestedNotifications(int $deliveryId,string $now):void{
        foreach(array('requested_student') as $kind)$this->insertNotification(array(
            'uid'=>\Delnavazan\Platform\Core\Support\Identifier::uid(),'delivery_id'=>$deliveryId,'confirmation_id'=>null,
            'notification_kind'=>$kind,'state'=>'queued','attempt_count'=>0,'next_attempt_at'=>$now,
            'lease_token_digest'=>null,'lease_expires_at'=>null,'last_error_code'=>null,'handed_off_at'=>null,
            'created_at'=>$now,'updated_at'=>$now,
        ));
    }
    public function notificationForDeliveryKind(int $deliveryId,string $kind):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_student_notifications WHERE delivery_id=%d AND notification_kind=%s",$deliveryId,$kind))?:null;}
    public function updateConfirmation(int $id,int $version,array $data):void{global $wpdb;$data['version']=$version+1;$n=$wpdb->update($this->p.'booking_request_confirmations',$data,array('id'=>$id,'version'=>$version));if($n!==1)throw new \RuntimeException('Booking confirmation changed concurrently');}
    public function transitionDelivery(int $id,string $from,string $to,string $now):void{global $wpdb;$n=$wpdb->update($this->p.'booking_request_teacher_deliveries',array('state'=>$to,'updated_at'=>$now,'responded_at'=>in_array($to,array('declined','confirmed'),true)?$now:null),array('id'=>$id,'state'=>$from));if($n!==1)throw new \RuntimeException('Booking request response changed concurrently');}
    public function createDelivery(array $data):int{return $this->insert('booking_request_teacher_deliveries',$data);}
    public function repointDelivery(int $id,int $teacherId,int $requestedTimeId,string $uid,string $matchStrength,string $now):void{
        global $wpdb;
        $changed=$wpdb->query($wpdb->prepare("UPDATE {$this->p}booking_request_teacher_deliveries SET uid=%s,teacher_id=%d,requested_time_id=%d,match_strength=%s,state='pending_request',updated_at=%s,responded_at=NULL WHERE id=%d AND state IN ('pending_request','declined','expired')",$uid,$teacherId,$requestedTimeId,$matchStrength,$now,$id));
        if($changed!==1)throw new \RuntimeException('Booking request claim changed concurrently');
    }
    public function switchOfferedTime(int $deliveryId,int $offerId,int $requestedTimeId,string $now):void{
        global $wpdb;
        $offer=$wpdb->query($wpdb->prepare("UPDATE {$this->p}booking_allocation_offers SET requested_time_id=%d WHERE id=%d AND state='pending' AND active_slot=1",$requestedTimeId,$offerId));
        if($offer!==1)throw new \RuntimeException('Booking offer changed concurrently');
        $delivery=$wpdb->query($wpdb->prepare("UPDATE {$this->p}booking_request_teacher_deliveries SET requested_time_id=%d,updated_at=%s WHERE id=%d AND state='pending_request'",$requestedTimeId,$now,$deliveryId));
        if($delivery!==1)throw new \RuntimeException('Booking delivery changed concurrently');
    }
    public function insertClaimOffer(int $requestId,int $deliveryId,int $teacherId,int $requestedTimeId,string $now,string $deadline):int{
        global $wpdb;
        $last=(int)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(MAX(offer_sequence),0) FROM {$this->p}booking_allocation_offers WHERE booking_request_id=%d",$requestId));
        if($wpdb->insert($this->p.'booking_allocation_offers',array('booking_request_id'=>$requestId,'delivery_id'=>$deliveryId,'teacher_id'=>$teacherId,'requested_time_id'=>$requestedTimeId,'offer_sequence'=>$last+1,'state'=>'pending','active_slot'=>1,'match_strength'=>'claim','offered_at'=>$now,'deadline_at'=>$deadline,'responded_at'=>null,'reason_code'=>'teacher_claim'))===false)throw new \RuntimeException('Booking claim offer persistence failed');
        return (int)$wpdb->insert_id;
    }
    public function closeRequest(int $id,string $resolution,string $now,int $actor):void{global $wpdb;$sql=$wpdb->prepare("UPDATE {$this->p}booking_requests SET lifecycle_status='closed',resolution_state=%s,version=version+1,updated_at=%s,updated_by=%d WHERE id=%d AND lifecycle_status='submitted' AND resolution_state='unresolved' AND privacy_erased_at IS NULL",$resolution,$now,$actor,$id);if($wpdb->query($sql)!==1)throw new \RuntimeException('Booking request changed concurrently');}
    public function retireSecret(int $id,int $actor,string $now):void{global $wpdb;$n=$wpdb->update($this->p.'provider_projection_secrets',array('state'=>'retired','active_slot'=>null,'retired_at'=>$now,'retired_by'=>$actor),array('id'=>$id,'state'=>'active','active_slot'=>1));if($n!==1)throw new \RuntimeException('Booking provider reference changed concurrently');}

    public function queuedNotifications(int $limit=10):array{global $wpdb;$limit=max(1,min(25,$limit));return (array)$wpdb->get_results("SELECT n.* FROM {$this->p}booking_request_student_notifications n WHERE (n.state IN ('queued','retryable') AND (n.next_attempt_at IS NULL OR n.next_attempt_at<=UTC_TIMESTAMP())) OR (n.state='sending' AND n.lease_expires_at<=UTC_TIMESTAMP()) ORDER BY n.id LIMIT {$limit}");}
    public function notificationPayload(int $id,bool $lock=false):?object{global $wpdb;$suffix=$lock?' FOR UPDATE':'';return $wpdb->get_row($wpdb->prepare("SELECT n.*,d.booking_request_id,d.teacher_id,d.state delivery_state,d.created_at delivery_created_at,r.student_id,r.lifecycle_status,r.resolution_state,COALESCE(c.state,'') confirmation_state,COALESCE(c.starts_at_utc,rt.starts_at_utc) starts_at_utc,COALESCE(c.ends_at_utc,rt.instructional_ends_at_utc) ends_at_utc,COALESCE(c.schedule_timezone,rt.timezone) schedule_timezone,c.id confirmation_record_id,s.email student_email,st.email student_account_email,st.phone student_account_phone,st.whatsapp_phone student_account_whatsapp,s.full_name,s.timezone student_timezone,s.communication_language student_language,st.locale student_locale,st.calendar_preference student_calendar,s.mobile student_mobile,s.whatsapp_number student_whatsapp,t.email teacher_email,t.timezone teacher_timezone,t.phone teacher_phone,t.whatsapp_phone teacher_whatsapp,COALESCE(NULLIF(t.display_name,''),NULLIF(t.english_name,''),t.persian_name) teacher_name,COALESCE(NULLIF(course.name_fa,''),course.name_en) course_name,p.id preparation_id,p.intro_lesson_id,p.uid preparation_uid,COALESCE(NULLIF(standard_course.name_fa,''),standard_course.name_en) preparation_course_name,slot.starts_at_utc slot_start_utc FROM {$this->p}booking_request_student_notifications n INNER JOIN {$this->p}booking_request_teacher_deliveries d ON d.id=n.delivery_id INNER JOIN {$this->p}booking_requests r ON r.id=d.booking_request_id INNER JOIN {$this->p}booking_request_contact_snapshots s ON s.booking_request_id=r.id AND s.snapshot_sequence=1 INNER JOIN {$this->p}booking_request_requested_times rt ON rt.id=d.requested_time_id INNER JOIN {$this->p}teachers t ON t.id=d.teacher_id LEFT JOIN {$this->p}students st ON st.id=r.student_id LEFT JOIN {$this->p}courses course ON course.id=r.selected_intro_course_id LEFT JOIN {$this->p}post_intro_preparations p ON p.booking_request_id=r.id LEFT JOIN {$this->p}courses standard_course ON standard_course.id=p.standard_course_id LEFT JOIN {$this->p}canonical_continuation_slot_authorities slot ON slot.intro_lesson_id=p.intro_lesson_id LEFT JOIN {$this->p}booking_request_confirmations c ON c.id=n.confirmation_id WHERE n.id=%d{$suffix}",$id))?:null;}
    public function notificationForUpdate(int $id):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}booking_request_student_notifications WHERE id=%d FOR UPDATE",$id))?:null;}
    public function auditByDigest(string $digest):?object{global $wpdb;return $wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->p}platform_audit_events WHERE idempotency_key=%s LIMIT 1",$digest))?:null;}
    public function insertAudit(array $data):int{return $this->insert('platform_audit_events',$data);}
    public function updateNotification(int $id,string $from,array $data,?string $leaseTokenDigest=null):void{global $wpdb;$where=array('id'=>$id,'state'=>$from);if($leaseTokenDigest!==null)$where['lease_token_digest']=$leaseTokenDigest;$n=$wpdb->update($this->p.'booking_request_student_notifications',$data,$where);if($n!==1)throw new \RuntimeException('Booking student notification changed concurrently');}

    private function insert(string $table,array $data):int{global $wpdb;if($wpdb->insert($this->p.$table,$data)===false)throw new \RuntimeException('Booking response persistence failed');return(int)$wpdb->insert_id;}
}
